package mx.edu.piloto;
import com.google.gson.*;import java.nio.file.*;import java.util.*;
/** Correcciones posteriores a metadatos, tramos explícitos y alta de paso confirmado. */
public final class CorpusCorreccionesConfirmadas {
 static JsonObject source(JsonObject original,String text,JsonObject ref,Path dir)throws Exception{
  Path file=CorpusMultidocumento.verified(dir,ref);if(!Files.readString(file).equals(text)||text.isBlank()||text.length()>3500)throw new IllegalArgumentException("Texto no corresponde a confirmación");
  var c=original.deepCopy();c.addProperty("texto",text);c.addProperty("fuente_texto",file.toString());c.addProperty("fuente_texto_sha256",OcrPagina.hash(file));c.addProperty("inicio_utf16",0);c.addProperty("fin_utf16_exclusivo",text.length());return c;
 }
 static void approved(JsonObject c,JsonObject u,Path proposals,Path approval)throws Exception{
  c.addProperty("contenido_confirmado_por_usuario",true);c.addProperty("nivel_revision","PARCIAL_DATOS_CRITICOS_EN_ENSAYO");c.addProperty("fragmentacion","UNIDAD_TRANSCRITA_CONFIRMADA");c.addProperty("revision_ocr_unidad",u.get("id").getAsString());
  c.addProperty("fuente_version",proposals.toString());c.addProperty("fuente_version_sha256",OcrPagina.hash(proposals));c.addProperty("confirmacion_documental",approval.toString());c.addProperty("confirmacion_sha256",OcrPagina.hash(approval));c.addProperty("literalidad","Transcripción de unidad confirmada; revisión parcial del PDF, no facsímil ni certificación normativa");
 }
 static List<JsonObject> apply(List<JsonObject> base,Path config)throws Exception{
  Path dir=config.toRealPath().getParent();var cfg=CorpusMultidocumento.read(config);if(!cfg.get("formato").getAsString().equals("correccion-ocr-tramos-y-alta-confirmada-v1"))throw new IllegalArgumentException("Revisión desconocida");
  Path pp=CorpusMultidocumento.verified(dir,cfg.getAsJsonObject("propuestas")),ap=CorpusMultidocumento.verified(dir,cfg.getAsJsonObject("confirmacion")),op=CorpusMultidocumento.verified(dir,cfg.getAsJsonObject("originales"));var proposal=CorpusMultidocumento.read(pp);var approval=CorpusMultidocumento.read(ap);
  if(!approval.get("estado").getAsString().equals("CONFIRMADO_POR_USUARIO")||!approval.get("propuestas_sha256").getAsString().equals(OcrPagina.hash(pp))||!approval.get("habilitar_paso11").getAsBoolean())throw new IllegalArgumentException("Confirmación incompleta");
  Set<String> approvals=new HashSet<>();for(var e:approval.getAsJsonArray("unidades"))if(!approvals.add(e.getAsString()))throw new IllegalArgumentException("Confirmación duplicada");
  Map<String,JsonObject> old=new LinkedHashMap<>();for(var c:base)if(old.put(c.get("id").getAsString(),c)!=null)throw new IllegalArgumentException("ID duplicado");Set<String> locked=new HashSet<>();for(var c:CorpusMultidocumento.rows(op)){String id=c.get("id").getAsString();if(!locked.add(id)||!c.equals(old.get(id)))throw new IllegalArgumentException("Origen de revisión alterado");}
  Map<String,JsonObject> replacements=new HashMap<>();Map<String,List<JsonObject>> after=new HashMap<>();Set<String> used=new HashSet<>(),requiredLocks=new HashSet<>();String releasedDoc=null;int releasedStep=-1;
  for(var e:proposal.getAsJsonArray("unidades")){
   var u=e.getAsJsonObject();String uid=u.get("id").getAsString(),kind=u.get("tipo").getAsString();if(!used.add(uid))throw new IllegalArgumentException("Unidad repetida");Path pdf=Path.of(u.get("pdf").getAsString());if(!OcrPagina.hash(pdf).equals(u.get("pdf_sha256").getAsString()))throw new IllegalArgumentException("PDF alterado");var textRef=cfg.getAsJsonObject("textos").getAsJsonObject(uid);
   if(kind.equals("CONFIRMACION_Y_PROPUESTA_HABILITACION_PASO_EXCLUIDO")){
    if(releasedDoc!=null)throw new IllegalArgumentException("Más de un alta de paso");var excluded=u.getAsJsonObject("original_excluido");Path ex=Path.of(u.get("fuente_exclusion").getAsString());if(!OcrPagina.hash(ex).equals(u.get("fuente_exclusion_sha256").getAsString())||CorpusMultidocumento.rows(ex).stream().noneMatch(excluded::equals)||!excluded.get("texto_fuente_propuesto").equals(u.get("texto_propuesto"))||!excluded.get("fuente_pdf_sha256").equals(u.get("pdf_sha256"))||excluded.get("numero").getAsInt()!=11||!excluded.get("unidad_id").getAsString().equals("anexo-paso-11")||!excluded.getAsJsonObject("documento").get("documento_id").equals(u.get("documento_id")))throw new IllegalArgumentException("Paso no corresponde a exclusión confirmada");
    releasedDoc=u.get("documento_id").getAsString();releasedStep=11;String doc=releasedDoc;List<JsonObject> candidates=base.stream().filter(c->c.get("documento_id").getAsString().equals(doc)).toList();
    var anchor=candidates.stream().filter(c->c.has("numero")&&!c.get("numero").isJsonNull()&&c.get("numero").getAsInt()==10).findFirst().orElseThrow();if(old.containsKey(excluded.get("id").getAsString())||candidates.stream().noneMatch(c->c.has("pasos_excluidos")&&c.getAsJsonArray("pasos_excluidos").asList().contains(new JsonPrimitive(11))))throw new IllegalArgumentException("El paso no estaba excluido");
    for(var c:candidates)requiredLocks.add(c.get("id").getAsString());if(!anchor.get("fuente_pdf_sha256").equals(u.get("pdf_sha256"))||anchor.get("pagina").getAsInt()!=u.get("pagina_pdf").getAsInt())throw new IllegalArgumentException("Ancla cruzada");
    var c=source(anchor,u.get("texto_propuesto").getAsString(),textRef,dir);c.add("id",excluded.get("id"));c.add("unidad_id",excluded.get("unidad_id"));c.add("numero",excluded.get("numero"));c.add("seccion",excluded.get("seccion"));c.add("relaciones_contexto",excluded.get("relaciones_contexto").deepCopy());c.addProperty("origen_exclusion",ex.toString());c.addProperty("origen_exclusion_sha256",OcrPagina.hash(ex));c.add("procedencia_ocr",excluded.get("procedencia_ocr").deepCopy());approved(c,u,pp,ap);after.put(anchor.get("id").getAsString(),List.of(c));
   }else{
    String id=u.get("fragmento_objetivo").getAsString();var original=old.get(id);if(original==null||!original.equals(u.get("fragmento_original"))||!original.get("documento_id").equals(u.get("documento_id"))||!original.get("fuente_pdf_sha256").equals(u.get("pdf_sha256"))||original.get("pagina").getAsInt()!=u.get("pagina_pdf").getAsInt()||replacements.containsKey(id))throw new IllegalArgumentException("Unidad cruzada");requiredLocks.add(id);
    var c=source(original,u.get("texto_propuesto").getAsString(),textRef,dir);approved(c,u,pp,ap);c.add("origen_fragmento_revisado",u.get("fragmento_original").deepCopy());
    if(kind.equals("CORRECCION_DE_TRAMO_CONTINUACION")){
     String full=original.get("texto").getAsString();int start=u.get("inicio_utf16").getAsInt(),end=u.get("fin_utf16_exclusivo").getAsInt();if(start<0||end<=start||end>full.length()||!full.substring(start,end).equals(u.get("texto_actual").getAsString()))throw new IllegalArgumentException("Tramo inválido");
     var restCfg=cfg.getAsJsonObject("restos").getAsJsonObject(uid);String rest=full.substring(0,start).stripTrailing()+"\n"+full.substring(end).stripLeading();var remainder=source(original,rest,restCfg.getAsJsonObject("texto"),dir);String restId=restCfg.get("id").getAsString();if(old.containsKey(restId))throw new IllegalArgumentException("ID de resto ya existe");remainder.addProperty("id",restId);remainder.addProperty("unidad_id",restId);remainder.addProperty("contenido_confirmado_por_usuario",false);remainder.addProperty("nivel_revision","OCR_AUTOMATICO_NO_REVISADO");remainder.addProperty("fragmentacion","REMANENTE_FUERA_DE_TRAMO_CONFIRMADO");remainder.addProperty("literalidad","Dos tramos de OCR original no revisados unidos por salto de línea; consultar PDF");remainder.add("origen_fragmento_revisado",u.get("fragmento_original").deepCopy());remainder.addProperty("tramo_excluido_inicio_utf16",start);remainder.addProperty("tramo_excluido_fin_utf16",end);remainder.remove("relaciones_contexto");after.put(id,List.of(remainder));c.addProperty("tramo_original_inicio_utf16",start);c.addProperty("tramo_original_fin_utf16",end);
    }else if(!kind.equals("SUSTITUCION_DE_REMANENTE_OCR")||!original.get("texto").equals(u.get("texto_actual")))throw new IllegalArgumentException("Sustitución no corresponde");
    replacements.put(id,c);
   }
  }
  if(!used.equals(approvals)||!locked.equals(requiredLocks)||releasedDoc==null)throw new IllegalArgumentException("Revisión incompleta");
  List<JsonObject> result=new ArrayList<>();for(var original:base){String id=original.get("id").getAsString();result.add(replacements.getOrDefault(id,original).deepCopy());if(after.containsKey(id))for(var c:after.get(id))result.add(c.deepCopy());}
  Set<String> seen=new HashSet<>();Map<String,Integer> order=new HashMap<>();Set<String> reordered=new HashSet<>();reordered.add(releasedDoc);for(String id:after.keySet())reordered.add(old.get(id).get("documento_id").getAsString());
  for(var c:result){String doc=c.get("documento_id").getAsString();if(!seen.add(c.get("id").getAsString()))throw new IllegalArgumentException("ID nuevo duplicado");if(doc.equals(releasedDoc)){var steps=new JsonArray();for(var n:c.getAsJsonArray("pasos_excluidos"))if(n.getAsInt()!=releasedStep)steps.add(n);c.add("pasos_excluidos",steps);c.addProperty("exclusion_paso11_resuelta_por",ap.toString());c.addProperty("exclusion_paso11_confirmacion_sha256",OcrPagina.hash(ap));}if(reordered.contains(doc)){int n=order.getOrDefault(doc,0)+1;order.put(doc,n);c.addProperty("orden",n);}}
  return result;
 }
}
